    "te": {
      "name": "ఆర్గానిక్ స్కిన్‌కేర్ గిఫ్ట్ సెట్",
      "description": "మీ రోజువారీ సౌందర్యం అనుభవాన్ని మెరుగుపరచడానికి రూపొందించబడిన అంతిమ ఆర్గానిక్ స్కిన్‌కేర్ గిఫ్ట్ సెట్ను కనుగొనండి.\n\nమినిమలిస్ట్ విధానం దీనికి సొగసైన, హుందాతనమైన రూపాన్ని ఇస్తుంది.\n\nదీని స్క్రాచ్-రెసిస్టెంట్ ఉపరితలం ప్రతిరోజూ కొత్తదానిలా మెరిసేలా చేస్తుంది.\n\nసామర్థ్యం విషయంలో రాజీ పడకుండా అత్యుత్తమ పనితీరు కోసం అనుకూలీకరించబడింది.\n\nఇది చూడటానికి బాగుండటమే కాకుండా మీ రోజువారీ పనులను మరింత సులభతరం చేస్తుంది.\n\nఈ అద్భుతమైన వస్తువును మీ సొంతం చేసుకునే అవకాశాన్ని కోల్పోకండి.",
      "category": "సౌందర్యం"
    },
    "kn": {
      "name": "ಸಾವಯವ ಸ್ಕಿನ್‌ಕೇರ್ ಉಡುಗೊರೆ ಸೆಟ್",
      "description": "ನಿಮ್ಮ ದೈನಂದಿನ ಸೌಂದರ್ಯ ಅನುಭವವನ್ನು ಹೆಚ್ಚಿಸಲು ವಿನ್ಯಾಸಗೊಳಿಸಲಾದ ಅತ್ಯುತ್ತಮ ಸಾವಯವ ಸ್ಕಿನ್‌ಕೇರ್ ಉಡುಗೊರೆ ಸೆಟ್ ಅನ್ನು ಅನ್ವೇಷಿಸಿ.\n\nಮಿನಿಮಲಿಸ್ಟ್ ವಿಧಾನವು ಇದಕ್ಕೆ ಸೊಗಸಾದ, ಗಂಭೀರ ನೋಟವನ್ನು ನೀಡುತ್ತದೆ.\n\nಇದರ ಸ್ಕ್ರ್ಯಾಚ್-ನಿರೋಧಕ ಮೇಲ್ಮೈಯು ಇದನ್ನು ಪ್ರತಿದಿನ ಹೊಚ್ಚ ಹೊಸದಾಗಿ ಇಡುತ್ತದೆ.\n\nಸಾಮರ್ಥ್ಯದಲ್ಲಿ ರಾಜಿ ಮಾಡಿಕೊಳ್ಳದೆ ಗರಿಷ್ಠ ದಕ್ಷತೆಗಾಗಿ ಆಪ್ಟಿಮೈಸ್ ಮಾಡಲಾಗಿದೆ.\n\nಇದು ನೋಡಲು ಸುಂದರವಾಗಿರುವುದಲ್ಲದೆ ನಿಮ್ಮ ದೈನಂದಿನ ದಿನಚರಿಯನ್ನು ಸಕ್ರಿಯವಾಗಿ ಸುಧಾರಿಸುತ್ತದೆ.\n\nಈ ಅಸಾಧಾರಣ ವಸ್ತುವನ್ನು ಹೊಂದಲು ಸಿಕ್ಕ ಅವಕಾಶವನ್ನು ಕಳೆದುಕೊಳ್ಳಬೇಡಿ.",
      "category": "ಸೌಂದರ್ಯ"
    },
    "hi": {
      "name": "ऑर्गेनिक स्किनकेयर गिफ़्ट सेट",
      "description": "अपने दैनिक सौंदर्य अनुभव को बेहतर बनाने के लिए विशेष रूप से डिज़ाइन किए गए सर्वोत्तम ऑर्गेनिक स्किनकेयर गिफ़्ट सेट को खोजें।\n\nएक न्यूनतम दृष्टिकोण इसे एक सुरुचिपूर्ण और सौम्य रूप देता है।\n\nइसकी खरोंच-रोधी सतह इसे हर दिन बिल्कुल नया बनाए रखती है।\n\nशक्ति से समझौता किए बिना चरम दक्षता के लिए अनुकूलित।\n\nयह न केवल दिखने में शानदार है बल्कि आपकी दैनिक दिनचर्या को भी बेहतर बनाता है।\n\nइस असाधारण वस्तु को पाने का अवसर हाथ से न जाने दें।",
      "category": "सौंदर्य"
    },
    "ta": {
      "name": "ஆர்கானிக் தோல் பராமரிப்பு பரிசு தொகுப்பு",
      "description": "உங்கள் அன்றாட அழகு சாதனங்கள் அனுபவத்தை உயர்த்த வடிவமைக்கப்பட்ட சிறந்த ஆர்கானிக் தோல் பராமரிப்பு பரிசு தொகுப்பு ஐக் கண்டறியவும்.\n\nமினிமலிஸ்ட் அணுகுமுறை இதற்கு நேர்த்தியான தோற்றத்தை அளிக்கிறது.\n\nகீறல்-எதிர்ப்பு மேற்பரப்பு இதை தினமும் புதியது போல் வைத்திருக்கிறது.\n\nசக்தியில் சமரசம் செய்யாமல் உச்சக்கட்ட செயல்திறனுக்காக உகந்ததாக்கப்பட்டது.\n\nஇது பார்ப்பதற்கு அழகாக இருப்பது மட்டுமல்லாமல் உங்கள் அன்றாட வழக்கத்தை தீவிரமாக மேம்படுத்துகிறது.\n\nஇந்த பிரத்யேகப் பொருளைப் பெறுவதற்கான வாய்ப்பைத் தவறவிடாதீர்கள்.",
      "category": "அழகு சாதனங்கள்"
    },
    "ml": {
      "name": "ഓർഗാനിക് സ്കിൻകെയർ ഗിഫ്റ്റ് സെറ്റ്",
      "description": "നിങ്ങളുടെ ദൈനംദിന സൗന്ദര്യം അനുഭവം ഉയർത്താൻ രൂപകൽപ്പന ചെയ്ത ആത്യന്തിക ഓർഗാനിക് സ്കിൻകെയർ ഗിഫ്റ്റ് സെറ്റ് കണ്ടെത്തുക.\n\nമിനിമലിസ്റ്റ് സമീപനം ഇതിന് മനോഹരമായ ലളിതമായ ലുക്ക് നൽകുന്നു.\n\nപോറലുകളെ പ്രതിരോധിക്കുന്ന ഉപരിതലം ഇതിനെ എന്നും പുതുമയോടെ സൂക്ഷിക്കുന്നു.\n\nപവർ കുറയ്ക്കാതെ തന്നെ മികച്ച കാര്യക്ഷമതയ്ക്കായി ഒപ്റ്റിമൈസ് ചെയ്തിരിക്കുന്നു.\n\nഇത് കാണാൻ മികച്ചത് മാത്രമല്ല, നിങ്ങളുടെ ദൈനംദിന ജീവിതം മെച്ചപ്പെടുത്തുകയും ചെയ്യുന്നു.\n\nഈ മികച്ച ഉൽപ്പന്നം സ്വന്തമാക്കാനുള്ള അവസരം നഷ്ടപ്പെടുത്തരുത്.",
      "category": "സൗന്ദര്യം"
    }
