window.currentLang = localStorage.getItem('shopease_lang') || 'en';

function t(key, lang) {
  const l = lang || window.currentLang || 'en';
  if (!key) return '';
  if (translations[l] && translations[l][key] !== undefined) {
    return translations[l][key];
  }
  return key;
}

function getCategoryName(slug, lang) {
  const l = lang || window.currentLang || 'en';
  if (!slug) return '';
  const s = slug.toLowerCase();
  if (categoryTranslations[s] && categoryTranslations[s][l]) {
    return categoryTranslations[s][l];
  }
  return slug.charAt(0).toUpperCase() + slug.slice(1);
}

function translateSpecValue(val, lang) {
  const l = lang || window.currentLang || 'en';
  if (!val || l === 'en') return val;
  if (specTranslations[val] && specTranslations[val][l]) {
    return specTranslations[val][l];
  }
  return val;
}

function getTranslatedProduct(p, lang) {
  if (!p) return p;
  const l = lang || window.currentLang || 'en';
  const originalName = p.name || '';
  const originalCategory = p.category || '';
  const originalDesc = p.description || '';

  if (l === 'en') {
    return {
      ...p,
      name: originalName,
      categoryName: getCategoryName(originalCategory, 'en'),
      description: originalDesc
    };
  }

  // Lookup by ID first, then by name
  let pt = null;
  if (p.id && productTranslations[p.id] && productTranslations[p.id][l]) {
    pt = productTranslations[p.id][l];
  } else if (p.product_id && productTranslations[p.product_id] && productTranslations[p.product_id][l]) {
    pt = productTranslations[p.product_id][l];
  } else {
    // Search in productTranslations or productNameTranslations
    for (const id in productTranslations) {
      if (productTranslations[id].en && productTranslations[id].en.name === originalName) {
        pt = productTranslations[id][l];
        break;
      }
    }
  }

  const translatedName = (pt && pt.name) ||
                         (productNameTranslations[p.id] && productNameTranslations[p.id][l]) ||
                         originalName;

  const translatedCat = (pt && pt.category) ||
                        getCategoryName(originalCategory, l) ||
                        originalCategory;

  const translatedDesc = (pt && pt.description) ||
                         (sentenceTranslations[originalDesc] && sentenceTranslations[originalDesc][l]) ||
                         originalDesc;

  return {
    ...p,
    name: translatedName,
    categoryName: translatedCat,
    description: translatedDesc
  };
}

function translateText(text, lang) {
  const l = lang || window.currentLang || 'en';
  if (!text || l === 'en') return text;
  if (translations[l] && translations[l][text]) return translations[l][text];
  if (sentenceTranslations[text] && sentenceTranslations[text][l]) return sentenceTranslations[text][l];
  return text;
}

function applyTranslation(node) {
  if (!node) return;
  const lang = window.currentLang || 'en';

  if (node.nodeType === Node.TEXT_NODE) {
    const text = node.nodeValue.trim();
    if (text) {
      if (node._origText === undefined) {
        // Check if text is known in translations.en or categoryTranslations
        const isKnownUi = translations.en && translations.en[text] !== undefined;
        let isKnownCat = false;
        for (const cat in categoryTranslations) {
          if (categoryTranslations[cat].en === text) { isKnownCat = true; break; }
        }
        if (isKnownUi || isKnownCat) {
          node._origText = text;
        }
      }
      const origText = node._origText;
      if (origText) {
        if (lang === 'en') {
          node.nodeValue = node.nodeValue.replace(text, origText);
        } else {
          let tr = translations[lang] && translations[lang][origText];
          if (!tr) {
            for (const cat in categoryTranslations) {
              if (categoryTranslations[cat].en === origText && categoryTranslations[cat][lang]) {
                tr = categoryTranslations[cat][lang];
                break;
              }
            }
          }
          if (tr) {
            node.nodeValue = node.nodeValue.replace(text, tr);
          }
        }
      }
    }
  } else if (node.nodeType === Node.ELEMENT_NODE) {
    if (node.tagName === 'SCRIPT' || node.tagName === 'STYLE') return;

    if (node.placeholder) {
      if (!node.dataset.origPlaceholder) node.dataset.origPlaceholder = node.placeholder;
      const orig = node.dataset.origPlaceholder;
      const tr = translations[lang] && translations[lang][orig];
      node.placeholder = tr ? tr : (lang === 'en' ? orig : node.placeholder);
    }

    if (node.title) {
      if (!node.dataset.origTitle) node.dataset.origTitle = node.title;
      const orig = node.dataset.origTitle;
      const tr = translations[lang] && translations[lang][orig];
      node.title = tr ? tr : (lang === 'en' ? orig : node.title);
    }

    if (node.hasAttribute('aria-label')) {
      const orig = node.dataset.origAria || node.getAttribute('aria-label');
      if (!node.dataset.origAria) node.dataset.origAria = orig;
      const tr = translations[lang] && translations[lang][orig];
      node.setAttribute('aria-label', tr ? tr : (lang === 'en' ? orig : node.getAttribute('aria-label')));
    }

    node.childNodes.forEach(child => applyTranslation(child));
  }
}

function updateCategoryPillsLanguage() {
  const wrap = document.getElementById('categories-scroll');
  if (!wrap) return;
  wrap.querySelectorAll('.category-pill').forEach(btn => {
    const cat = btn.dataset.category;
    if (cat) {
      const catName = getCategoryName(cat, window.currentLang);
      const iconSpan = btn.querySelector('.cat-icon');
      const iconHtml = iconSpan ? iconSpan.outerHTML : '';
      btn.innerHTML = `${iconHtml}${catName}`;
    }
  });
}

function updateLanguage(lang) {
  window.currentLang = lang;
  localStorage.setItem('shopease_lang', lang);

  // Apply DOM-level text replacements
  applyTranslation(document.body);

  // Update modal active buttons
  document.querySelectorAll('.lang-btn').forEach(btn => {
    btn.classList.toggle('btn-primary', btn.dataset.lang === lang);
    btn.classList.toggle('btn-secondary', btn.dataset.lang !== lang);
  });

  // Update categories bar
  updateCategoryPillsLanguage();

  // Update search input placeholder
  const searchInput = document.getElementById('search-input');
  if (searchInput) {
    searchInput.placeholder = t('Search products, categories, brands...');
  }

  // Dynamically re-render the active storefront view so translated products appear immediately
  if (typeof state !== 'undefined' && state) {
    if (!state.currentView || state.currentView === 'home') {
      if (typeof loadProducts === 'function') loadProducts();
      if (typeof loadFeatured === 'function') loadFeatured();
    } else if (state.currentView === 'product-detail' && state.currentProductId) {
      if (typeof renderProductDetail === 'function') renderProductDetail(state.currentProductId);
    } else if (state.currentView === 'cart') {
      if (typeof renderCart === 'function') renderCart();
    } else if (state.currentView === 'wishlist') {
      if (typeof renderWishlist === 'function') renderWishlist();
    } else if (state.currentView === 'checkout') {
      if (typeof renderCheckout === 'function') renderCheckout();
    } else if (state.currentView === 'orders') {
      if (typeof loadOrders === 'function') loadOrders();
    }
  }
}

function initLanguageSelector() {
  const languages = [
    { code: 'en', label: 'English' },
    { code: 'te', label: 'తెలుగు (Telugu)' },
    { code: 'kn', label: 'ಕನ್ನಡ (Kannada)' },
    { code: 'hi', label: 'हिन्दी (Hindi)' },
    { code: 'ta', label: 'தமிழ் (Tamil)' },
    { code: 'ml', label: 'മലയാളം (Malayalam)' }
  ];

  const optsContainer = document.getElementById('language-options');
  if (optsContainer) {
    optsContainer.innerHTML = languages.map(l => 
      `<button type="button" class="btn ${window.currentLang === l.code ? 'btn-primary' : 'btn-secondary'} lang-btn" data-lang="${l.code}" style="text-align:left; justify-content:flex-start; width:100%; font-size:1rem; padding:0.75rem 1rem;">${l.label}</button>`
    ).join('');
  }

  const modal = document.getElementById('language-modal');
  const backdrop = document.getElementById('language-modal-backdrop');

  document.body.addEventListener('click', (e) => {
    const langItem = e.target.closest('#language-item, #mobile-language-item, #settings-language-btn');
    if (langItem) {
      modal.style.display = 'flex';
      backdrop.style.display = 'block';
      const pd = document.getElementById('profile-dropdown');
      if (pd) pd.style.display = 'none';
      const mpd = document.getElementById('mobile-profile-dropdown');
      if (mpd) mpd.style.display = 'none';
    }

    const langBtn = e.target.closest('.lang-btn');
    if (langBtn) {
      updateLanguage(langBtn.dataset.lang);
      modal.style.display = 'none';
      backdrop.style.display = 'none';
    }

    if (e.target.closest('#language-modal-close') || e.target === backdrop) {
      modal.style.display = 'none';
      backdrop.style.display = 'none';
    }
  });

  setTimeout(() => {
    applyTranslation(document.body);
    updateCategoryPillsLanguage();
  }, 100);

  const observer = new MutationObserver((mutations) => {
    if (mutations.some(m => m.addedNodes.length > 0)) {
      observer.disconnect();
      applyTranslation(document.body);
      observer.observe(document.body, { childList: true, subtree: true });
    }
  });
  observer.observe(document.body, { childList: true, subtree: true });
}

document.addEventListener('DOMContentLoaded', initLanguageSelector);
